import { AnalyticsData, AstrologyProfile, Astrologer, AuthSession, ChatResponse, ConsultationRecord, DailyReflection as DailyReflectionRecord, DashboardData, LifeEvent, Memory, Report, ResonanceData, User } from "@/lib/types";
import { dateFromISO, daysFromToday, fullDateLabel, futureISODate, greeting, localISODate } from "@/lib/date";
import { Button, Card, EmptyState, ErrorState, Loading, Logo, PageTitle, Progress, ScoreRing } from "./ui";
import { ArrowRight, Bell, BookOpen, Briefcase, CalendarDays, Check, ChevronDown, CircleUserRound, Clock3, Copy, DollarSign, ExternalLink, Heart, Home, LayoutDashboard, Link2, LogIn, LogOut, Menu, MessageCircle, MoonStar, Orbit, Plus, Send, Settings, Share2, ShieldCheck, Sparkles, Star, Target, Trash2, TrendingUp, UserRound, Users, WandSparkles, X, Zap } from "lucide-react";

const nav=[
  ["/dashboard","Home",Home],["/ask","Ask AstroTwin",MessageCircle],["/chart","Vedic Chart",Orbit],["/timeline","Life Timeline",CalendarDays],["/daily","Cosmic Daily",MoonStar],["/circle","AstroCircle",Users],["/memories","Memories",BookOpen],["/astrologers","Astrologers",UserRound]
] as const;
const suggested=["What does my Vedic chart suggest for my upcoming interview?","What relationship patterns appear in my 7th house and Moon?","How is my current mahadasha shaping this period?","Help me reflect on an important decision.","What do my current transits emphasize?"];

function go(path:string){ window.location.href=path; }
function daysUntil(d:string){const n=daysFromToday(d); return n===0?"Today":n>0?`${n} day${n===1?"":"s"} remaining`:`${Math.abs(n)} days ago`}
function formatDate(d:string){return dateFromISO(d).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"})}

export function AstroTwinApp(){
  const path=usePathname(); const router=useRouter();
  const [session,setSession]=useState<AuthSession|null>(null); const [ready,setReady]=useState(false);
  useEffect(()=>{api<AuthSession>("/api/auth/me").then(setSession).catch(()=>setSession(null)).finally(()=>setReady(true))},[]);
  const activateDemo=async()=>{try{await post<{userId:number}>("/api/demo/activate",{});go("/dashboard")}catch(error){alert(error instanceof Error?error.message:"AstroTwin could not start the demo. Please try again.")}};
  if(path==="/") return <Landing onDemo={activateDemo}/>;
  if(path==="/onboarding") return <Onboarding onComplete={()=>go("/dashboard")}/>;
  if(path==="/login") return <Login onComplete={()=>go("/dashboard")}/>;
  if(path.startsWith("/circle/share/")) return <SharedReport shareId={path.split("/").pop()!}/>;
  if(!ready) return <Loading/>;
  if(!session) return <AccessGate onDemo={activateDemo}/>;
  return <Shell path={path} user={session.user} isDemo={session.isDemo}><Route path={path} userId={session.user.id} router={router}/></Shell>;
}

function Landing({onDemo}:{onDemo:()=>void}){
 const modules=[
  [BookOpen,"AstroTwin Memory","Your goals, events and reflections become a living context—not another forgotten chat.","/memories"],
  [MoonStar,"Cosmic Daily","A personalized daily ritual for focus, reflection and guidance alignment.","/daily"],
  [Users,"AstroCircle","Beautiful compatibility reflections designed to be shared with people who matter.","/circle"],
  [UserRound,"AstroConnect","Human astrologers appear when a question deserves a deeper conversation.","/astrologers"]
 ] as const;
 return <main className="landing"><nav className="landingNav"><Logo/><div><button className="textButton" onClick={()=>go("/login")}>Sign in</button><button className="textButton" onClick={onDemo}>Explore Demo</button><Button onClick={()=>go("/onboarding")}>Create Your AstroTwin</Button></div></nav>
  <section className="hero"><div className="heroGlow"/><div className="heroCopy"><div className="pill"><Sparkles size={14}/> Astrology that remembers your life</div><h1>Meet the astrology companion that <em>remembers your life.</em></h1><p>AstroTwin connects your birth profile, goals, important life events and daily reflections to create guidance that evolves with you.</p><div className="heroActions"><Button onClick={()=>go("/onboarding")}>Create Your AstroTwin <ArrowRight size={18}/></Button><Button variant="secondary" onClick={onDemo}>Explore Demo <ExternalLink size={17}/></Button></div><div className="trust"><span><Check/>No account needed for demo</span><span><ShieldCheck/>Reflective, responsible guidance</span></div></div>
  <div className="heroProduct"><div className="orbit one"/><div className="orbit two"/><Card className="preview"><div className="previewTop"><span>Today · {new Date().toLocaleDateString("en-IN",{day:"numeric",month:"long"})}</span><span className="liveDot">Live insight</span></div><div className="previewScore"><ScoreRing value={82}/><div><span>Cosmic Momentum</span><h3>Your energy favors focused progress.</h3><p>With AstroHack approaching, protect your clearest hours for the work only you can do.</p></div></div><div className="miniBars"><Progress label="Career" value={91}/><Progress label="Focus" value={86}/></div><div className="memoryFlag"><BookOpen size={17}/><span>Personalized using <b>4 memories</b></span></div></Card></div></section>
  <section className="socialProof"><span>PROFILE</span><i/><span>DAILY GUIDANCE</span><i/><span>REFLECTION</span><i/><span>MEMORY</span><i/><span>HUMAN CONNECTION</span></section>
  <section className="section intro"><div className="eyebrow">A persistent astrology identity</div><h2>Most astrology experiences forget you. <span>AstroTwin grows with you.</span></h2><p>It turns isolated consultations into an evolving relationship—connecting today’s choices with the context of your life.</p></section>
  <section className="moduleGrid">{modules.map(([Icon,title,body,href],i)=><Card key={title} className={`moduleCard m${i}`}><span className="iconBox"><Icon/></span><small>0{i+1}</small><h3>{title}</h3><p>{body}</p><a className="learn" href={href}>Explore module <ArrowRight size={16}/></a></Card>)}</section>
  <section className="how"><div><div className="eyebrow">The personal flywheel</div><h2>Every interaction makes the next one more relevant.</h2></div><div className="steps">{["Build your profile","Receive daily guidance","Reflect on what resonated","Grow a richer memory","Connect when it matters"].map((x,i)=><div key={x}><b>{i+1}</b><span>{x}</span>{i<4&&<ArrowRight/>}</div>)}</div></section>
  <section className="finalCta"><Sparkles/><h2>Your life changes. Your guidance should remember.</h2><p>Start with the full demo, or create an AstroTwin that begins with what matters to you now.</p><div><Button onClick={()=>go("/onboarding")}>Create Your AstroTwin</Button><Button variant="secondary" onClick={onDemo}>View Demo</Button></div></section>
  <footer><Logo/><p>Astrology-based reflective guidance for entertainment and personal exploration.</p><span>AstroHack 2026 · Built for AstroLive</span></footer>
 </main>
}

function Login({onComplete}:{onComplete:()=>void}){const[form,setForm]=useState({email:"",password:""});const[error,setError]=useState("");const[loading,setLoading]=useState(false);const submit=async()=>{setLoading(true);setError("");try{await post("/api/auth/login",form);onComplete()}catch(e){setError(e instanceof Error?e.message:"Unable to sign in");setLoading(false)}};return <main className="authPage"><Logo/><Card className="authCard"><div className="iconBox"><LogIn/></div><span className="eyebrow">WELCOME BACK</span><h1>Continue your AstroTwin.</h1><p>Your chart, memories and conversations are connected to your account.</p><label>Email<input type="email" autoComplete="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Password<input type="password" autoComplete="current-password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} onKeyDown={e=>{if(e.key==="Enter")submit()}}/></label>{error&&<p className="errorText">{error}</p>}<Button disabled={!form.email||!form.password||loading} onClick={submit}>{loading?"Signing in…":"Sign in"}</Button><p className="authSwitch">New to AstroTwin? <a href="/onboarding">Create an account</a></p></Card></main>}

function Onboarding({onComplete}:{onComplete:()=>void}){
 const [step,setStep]=useState(1);const [loading,setLoading]=useState(false);const [error,setError]=useState("");
 const [form,setForm]=useState({name:"",email:"",password:"",birth_date:"",birth_time:"",birth_city:"",interests:["Career"],current_focus:"",primary_focus:"Career"});
 const interests=["Career","Relationships","Finance","Personal Growth","Education","Family"];
 const submit=async()=>{setLoading(true);setError("");try{await post("/api/auth/signup",form);setStep(4);setTimeout(onComplete,2200)}catch(e){setError(e instanceof Error?e.message:"Unable to create AstroTwin");setLoading(false)}};
 return <main className="onboarding"><div className="onboardingBrand"><Logo/><p>Astrology that remembers your life.</p><div className="constellation"/></div><div className="onboardingForm"><div className="stepper">{[1,2,3,4].map(n=><span key={n} className={n<=step?"active":""}>{n<step?<Check/>:n}</span>)}</div>
  {step===1&&<div className="formStep"><div className="eyebrow">Step 1 of 4</div><h1>Create your account and chart.</h1><p>Your exact birth details are used to calculate a private Lahiri sidereal chart.</p><label>Your name<input autoComplete="name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="How should we address you?"/></label><div className="formGrid"><label>Email<input type="email" autoComplete="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Password<input type="password" minLength={8} autoComplete="new-password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} placeholder="At least 8 characters"/></label></div><div className="formGrid"><label>Date of birth<input type="date" value={form.birth_date} onChange={e=>setForm({...form,birth_date:e.target.value})}/></label><label>Exact birth time<input type="time" value={form.birth_time} onChange={e=>setForm({...form,birth_time:e.target.value})}/></label></div><label>Birth city and country<input value={form.birth_city} onChange={e=>setForm({...form,birth_city:e.target.value})} placeholder="e.g. Jaipur, India"/></label><Button disabled={!form.name||!form.email||form.password.length<8||!form.birth_date||!form.birth_time||!form.birth_city} onClick={()=>setStep(2)}>Continue <ArrowRight/></Button></div>}
  {step===2&&<div className="formStep"><div className="eyebrow">Step 2 of 4</div><h1>What matters most?</h1><p>Select the life areas you’d like AstroTwin to remember and reflect with you.</p><div className="choiceGrid">{interests.map(x=><button key={x} className={form.interests.includes(x)?"selected":""} onClick={()=>setForm({...form,interests:form.interests.includes(x)?form.interests.filter(i=>i!==x):[...form.interests,x],primary_focus:form.primary_focus||x})}>{x}<Check/></button>)}</div><label>Primary focus<select value={form.primary_focus} onChange={e=>setForm({...form,primary_focus:e.target.value})}>{form.interests.map(i=><option key={i}>{i}</option>)}</select></label><div className="row"><Button variant="ghost" onClick={()=>setStep(1)}>Back</Button><Button onClick={()=>setStep(3)}>Continue <ArrowRight/></Button></div></div>}
  {step===3&&<div className="formStep"><div className="eyebrow">Step 3 of 4</div><h1>What’s happening right now?</h1><p>This becomes your AstroTwin’s first meaningful memory.</p><label>Current focus<textarea rows={5} value={form.current_focus} onChange={e=>setForm({...form,current_focus:e.target.value})} placeholder="What’s the biggest thing happening in your life right now?"/></label>{error&&<p className="errorText">{error}</p>}<div className="row"><Button variant="ghost" onClick={()=>setStep(2)}>Back</Button><Button disabled={!form.current_focus||loading} onClick={submit}>Generate AstroTwin <WandSparkles/></Button></div></div>}
  {step===4&&<div className="generating"><div className="generationOrb"><Sparkles/></div><div className="eyebrow">Creating your AstroTwin…</div><h1>Calculating your Vedic chart.</h1><p>Resolving birthplace, computing Lahiri sidereal placements and connecting your first memory.</p><div className="loadingLine"><i/></div></div>}
 </div></main>
}

function Shell({path,user,isDemo,children}:{path:string;user:User;isDemo:boolean;children:React.ReactNode}){
 const [mobile,setMobile]=useState(false);
 return <div className="appShell"><aside className={mobile?"open":""}><div className="sideTop"><Logo/><button className="closeMobile" aria-label="Close navigation" onClick={()=>setMobile(false)}><X/></button></div><div className="navLabel">YOUR ASTROTWIN</div><nav>{nav.map(([href,label,Icon])=><a key={href} href={href} className={path===href||path.startsWith(href+"/")?"active":""}><Icon/><span>{label}</span></a>)}</nav><div className="sideBottom"><a href="/settings"><Settings/><span>Settings</span></a><a href="/admin/analytics"><LayoutDashboard/><span>Demo Analytics</span></a><button className="sideSignOut" onClick={async()=>{await post("/api/auth/logout",{});go("/")}}><LogOut/><span>Sign out</span></button><div className="disclaimer">Reflective guidance, not professional advice.</div></div></aside>{mobile&&<button className="mobileBackdrop" aria-label="Close navigation" onClick={()=>setMobile(false)}/>}<main className="workspace"><header className="topbar"><button className="menu" aria-label="Open navigation" onClick={()=>setMobile(true)}><Menu/></button><div className="demoBadge"><span/> {isDemo?"Seeded demo profile":"Authenticated profile"}</div><div className="topActions"><a href="/settings" aria-label="Notification preferences"><Bell/></a><a href="/settings" className="avatar" aria-label="Profile settings">{user.name[0]?.toUpperCase()}</a></div></header><div className="content">{children}</div></main><nav className="bottomNav" aria-label="Primary mobile navigation">{nav.slice(0,5).map(([href,label,Icon])=><a key={href} href={href} className={path===href?"active":""}><Icon/><span>{label.replace("AstroTwin","")}</span></a>)}</nav></div>
}

function Route({path,userId,router}:{path:string;userId:number;router:ReturnType<typeof useRouter>}){
 if(path==="/dashboard")return <Dashboard userId={userId}/>;
 if(path==="/ask")return <Ask userId={userId}/>;
 if(path==="/chart")return <VedicChartView userId={userId}/>;
 if(path==="/timeline")return <Timeline userId={userId}/>;
 if(path==="/memories")return <Memories userId={userId}/>;
 if(path==="/daily")return <Daily userId={userId}/>;
 if(path==="/resonance")return <Resonance userId={userId}/>;
 if(path==="/circle")return <Circle userId={userId}/>;
 if(path.startsWith("/circle/result/"))return <ReportView id={path.split("/").pop()!}/>;
 if(path==="/astrologers")return <Astrologers/>;
 if(path.startsWith("/astrologers/"))return <AstrologerProfile id={path.split("/").pop()!} userId={userId}/>;
 if(path.startsWith("/consultation/"))return <Consultation id={path.split("/").pop()!} userId={userId}/>;
 if(path==="/settings")return <SettingsView userId={userId}/>;
 if(path==="/admin/analytics")return <Analytics/>;
 return <EmptyState title="This constellation is still forming" body="The page you requested doesn’t exist." action={<Button onClick={()=>router.push("/dashboard")}>Return home</Button>}/>;
}

function useLoad<T>(loader:()=>Promise<T>,deps:unknown[]){const [data,setData]=useState<T|null>(null);const[error,setError]=useState("");const load=useCallback(()=>{setError("");loader().then(setData).catch(e=>setError(e.message))},deps);useEffect(load,[load]);return{data,error,reload:load,setData}}

function Dashboard({userId}:{userId:number}){
 const {data,error,reload}=useLoad(()=>api<DashboardData>(`/api/users/${userId}/dashboard`),[userId]);
 if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;const g=data.guidance;
 const astro=data.recommended_astrologer;
 const isDemo=data.user.email==="demo@astrotwin.local";
 return <><PageTitle eyebrow={fullDateLabel().toUpperCase()} title={`${greeting()}, ${data.user.name}`} description="Here’s the pattern your AstroTwin sees across today and what’s ahead." action={<div className="pageActions">{isDemo&&<span className="demoProfileBadge"><CircleUserRound/> Seeded demo profile</span>}<Button onClick={()=>go("/ask")}>Ask AstroTwin <Sparkles/></Button></div>}/><div className="dashboardGrid"><Card className="momentum"><div className="cardHead"><div><span className="sectionKicker">TODAY’S SIGNAL</span><h2>Cosmic Momentum</h2></div><span className="delta"><CalendarDays/> Personalized today</span></div><div className="scoreLayout"><ScoreRing value={g.overall_score}/><div className="scoreBars"><Progress label="Career" value={g.career_score}/><Progress label="Relationships" value={g.relationship_score}/><Progress label="Finance" value={g.finance_score}/><Progress label="Focus / Energy" value={g.energy_score}/></div></div></Card>
 <Card className="guidance"><div className="cardHead"><span className="iconBox"><MoonStar/></span><span className="memoryCount"><BookOpen/> Using {data.memories.length} memories</span></div><span className="sectionKicker">TODAY’S GUIDANCE</span><h2>{g.insight}</h2><p>Your strongest window is built around intentional momentum, not pressure. Let your next step be small enough to begin and meaningful enough to matter.</p><div className="actionBox"><Target/><div><small>RECOMMENDED ACTION</small><b>{g.recommended_action}</b></div></div></Card>
 <Card className="events"><div className="cardHead"><div><span className="sectionKicker">LIFE TIMELINE</span><h2>Upcoming events</h2></div><a href="/timeline">View timeline <ArrowRight/></a></div><div className="eventList">{data.events.length?data.events.slice(0,3).map((e,i)=><div key={e.id} className="eventRow"><div className="dateTile"><b>{dateFromISO(e.date).getDate()}</b><span>{dateFromISO(e.date).toLocaleDateString("en",{month:"short"})}</span></div><div><b>{e.title}</b><span>{e.category} · {daysUntil(e.date)}</span></div><i className={`eventColor c${i}`}/></div>):<div className="inlineEmpty"><CalendarDays/><span><b>No upcoming events yet</b><small>Add a milestone to personalize future guidance.</small></span></div>}</div></Card>
 <Card className="memories"><div className="cardHead"><div><span className="sectionKicker">PERSISTENT CONTEXT</span><h2>AstroTwin Memory</h2></div><a href="/memories">View all <ArrowRight/></a></div><div className="memoryGrid">{data.memories.length?data.memories.slice(0,4).map(m=><div key={m.id} className="memoryChip"><span>{m.type}</span><p>{m.content}</p></div>):<div className="inlineEmpty"><BookOpen/><span><b>No memories saved</b><small>Add a goal or reflection to begin.</small></span></div>}</div></Card>
 <Reflection userId={userId} existing={data.reflection}/><Card className="teaser circleTeaser"><span className="iconBox"><Users/></span><div><span className="sectionKicker">ASTROCIRCLE</span><h3>Explore a connection</h3><p>Create a shareable compatibility reflection.</p></div><Button variant="secondary" onClick={()=>go("/circle")}>Create match</Button></Card>{astro&&<Card className="teaser connectTeaser"><span className="avatar big">{astro.name.split(" ").map(x=>x[0]).join("")}</span><div><span className="sectionKicker">RECOMMENDED FOR {astro.specialization.toUpperCase()}</span><h3>{astro.name} <span className={astro.availability}>{astro.availability}</span></h3><p><Star/> {astro.rating} · {astro.experience_years} years · ₹{astro.price_per_minute}/min</p></div><Button onClick={()=>go(`/astrologers/${astro.id}`)}>View profile</Button></Card>}</div></>
}

function Reflection({userId,existing}:{userId:number;existing?:DailyReflectionRecord|null}){const[mood,setMood]=useState(existing?.mood||"");const[resonance,setResonance]=useState(existing?.resonance||"");const[done,setDone]=useState(Boolean(existing));const[saving,setSaving]=useState(false);const[error,setError]=useState("");const submit=async()=>{setSaving(true);setError("");try{await post(`/api/users/${userId}/reflection`,{date:localISODate(),mood,resonance});setDone(true)}catch(e){setError(e instanceof Error?e.message:"Could not save your reflection.")}finally{setSaving(false)}};return <Card className="reflection"><span className="sectionKicker">DAILY REFLECTION</span><h2>{done?"Today’s reflection is saved":"How did today feel?"}</h2>{done?<><div className="success"><Check/> {mood} · {resonance} resonant</div><p>Your AstroTwin will carry this context forward.</p><Button variant="secondary" onClick={()=>setDone(false)}>Update reflection</Button></>:<><div className="segmented">{["Great","Normal","Difficult"].map(x=><button key={x} className={mood===x?"active":""} onClick={()=>setMood(x)}>{x}</button>)}</div><p>Did today’s guidance resonate?</p><div className="resonanceButtons">{["Strongly","Partially","Not really"].map(x=><button key={x} className={resonance===x?"active":""} onClick={()=>setResonance(x)}>{x}</button>)}</div>{error&&<p className="errorText">{error}</p>}<Button disabled={!mood||!resonance||saving} onClick={submit}>{saving?"Saving…":"Save reflection"}</Button></>}</Card>}

function Ask({userId}:{userId:number}){
 const[messages,setMessages]=useState<{role:"user"|"assistant";content:string;meta?:ChatResponse}[]>([{role:"assistant",content:`${greeting()}. I have your goals, upcoming milestones and recent reflections in view. What would you like to explore?`}]);const[input,setInput]=useState("");const[typing,setTyping]=useState(false);const[conversationId,setConversationId]=useState<number|null>(null);
 const send=async(q=input)=>{const question=q.trim();if(!question||typing)return;setInput("");setMessages(m=>[...m,{role:"user",content:question}]);setTyping(true);try{const r=await post<ChatResponse>("/api/chat",{user_id:userId,question,conversation_id:conversationId});setConversationId(r.conversationId);setMessages(m=>[...m,{role:"assistant",content:r.response,meta:r}])}catch(e){setMessages(m=>[...m,{role:"assistant",content:e instanceof Error?e.message:"I couldn’t reach your memory right now. Please try once more."}])}finally{setTyping(false)}};
 return <div className="chatPage"><PageTitle eyebrow="VEDIC CHART + PERSISTENT MEMORY" title="Ask AstroTwin" description="Explore your computed Lahiri sidereal chart alongside relevant goals, events and reflections."/><Card className="chat"><div className="chatContext"><Sparkles/><div><b>Your verified chart context is ready</b><span>Lagna · Moon · Nakshatra · Mahadasha · Current transits · Relevant memories</span></div><ChevronDown/></div><div className="messages" aria-live="polite">{messages.map((m,i)=><div key={i} className={`message ${m.role}`}><div className="messageAvatar">{m.role==="assistant"?<Sparkles/>:"A"}</div><div>{m.meta&&<div className="responseBasis"><span className="using"><Orbit/> {m.meta.astrologyBasis.lagna} Lagna · {m.meta.astrologyBasis.moon_sign} Moon</span><span className="using"><MoonStar/> {m.meta.astrologyBasis.nakshatra} · {m.meta.astrologyBasis.mahadasha} mahadasha</span><span className="using"><Sparkles/> {m.meta.provider.startsWith("groq:")?"Groq conversational AI":m.meta.provider==="local-fallback"?"Local Vedic fallback":"Local Vedic engine"}</span>{m.meta.memoryCount>0&&<span className="using"><BookOpen/> Using {m.meta.memoryCount} relevant {m.meta.memoryCount===1?"memory":"memories"}</span>}</div>}<p>{m.content}</p>{m.meta&&<details><summary>Chart and context used</summary><div className="contextChips"><span>{m.meta.astrologyBasis.system}</span><span>{m.meta.astrologyBasis.ayanamsa} ayanamsa</span><span>{m.meta.astrologyBasis.sun_sign} Sun</span>{m.meta.contextUsed.memories.slice(0,3).map(x=><span key={`m-${x.id}`}>{x.content}</span>)}{m.meta.contextUsed.events.slice(0,2).map(x=><span key={`e-${x.id}`}>{x.title}</span>)}</div></details>}{m.meta?.intent?.recommendAstrologer&&m.meta.intent.specialization&&<AstroConnect specialization={m.meta.intent.specialization} userId={userId}/>}</div></div>)}{typing&&<div className="message assistant"><div className="messageAvatar"><Sparkles/></div><div className="typing"><i/><i/><i/></div></div>}</div><div className="suggestions">{suggested.slice(0,3).map(x=><button key={x} onClick={()=>send(x)}>{x}</button>)}</div><div className="composer"><textarea maxLength={5000} value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send()}}} placeholder="Ask about career, relationships, timing, dasha or transits…" rows={1}/><button disabled={!input.trim()||typing} onClick={()=>send()} aria-label="Send message"><Send/></button></div><small className="chatNote">Chart positions are computed with Swiss Ephemeris in Lahiri sidereal mode. Interpretations are belief-based reflections—not certainty or professional advice. {input.length}/5000</small></Card></div>
}
function VedicChartView({userId}:{userId:number}){const{data,error,reload}=useLoad(()=>api<AstrologyProfile>(`/api/users/${userId}/astrology-profile`),[userId]);if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;const c=data.chart;return <><PageTitle eyebrow="COMPUTED BIRTH CHART" title="Your Vedic Chart" description={`Lahiri sidereal chart calculated for ${data.resolved_place} (${data.timezone}).`} action={<Button onClick={()=>go("/ask")}>Ask about this chart <Sparkles/></Button>}/><div className="chartSummary"><Card><span>Lagna</span><strong>{c.ascendant.rashi}</strong><small>{c.ascendant.degree}° · {c.ascendant.nakshatra} pada {c.ascendant.pada}</small></Card><Card><span>Chandra Rashi</span><strong>{c.moon_sign}</strong><small>{c.janma_nakshatra.name} pada {c.janma_nakshatra.pada}</small></Card><Card><span>Surya Rashi</span><strong>{c.sun_sign}</strong><small>Lahiri sidereal Sun</small></Card><Card><span>Mahadasha</span><strong>{c.current_mahadasha.lord}</strong><small>{formatDate(c.current_mahadasha.start)} – {formatDate(c.current_mahadasha.end)}</small></Card></div><Card className="planetTable"><div className="cardHead"><div><span className="sectionKicker">NATAL GRAHA POSITIONS</span><h2>Planetary placements</h2></div><span className="dataMode"><span/> Swiss Ephemeris · Lahiri</span></div><div className="planetRows"><div className="planetHeader"><span>Graha</span><span>Rashi</span><span>Degree</span><span>House</span><span>Nakshatra</span></div>{c.planets.map(p=><div key={p.name}><b>{p.name}{p.retrograde?" ℞":""}</b><span>{p.rashi}</span><span>{p.degree}°</span><span>{p.house}</span><span>{p.nakshatra} · P{p.pada}</span></div>)}</div></Card><Card className="chartNotice"><ShieldCheck/><div><b>Calculation versus interpretation</b><p>{c.calculation_notice}</p></div></Card></>}
function AstroConnect({specialization,userId}:{specialization:string;userId:number}){const{data}=useLoad(()=>api<Astrologer[]>(`/api/astrologers?specialization=${encodeURIComponent(specialization)}`),[specialization]);const astrologer=data?.[0];const openProfile=async()=>{if(!astrologer)return go(`/astrologers?specialization=${encodeURIComponent(specialization)}`);await post("/api/analytics/event",{event_name:"astrologer_profile_viewed",user_id:userId,metadata:{source:"astrotwin_recommendation",specialization}}).catch(()=>{});go(`/astrologers/${astrologer.id}`)};return <div className="connectCard"><div><span className="pill"><UserRound/> ASTROCONNECT</span><h3>Want a deeper {specialization.toLowerCase()} reading?</h3><p>A human astrologer can explore the nuances of this decision with you.</p></div>{astrologer?<div className="miniAstro"><span className="avatar">{astrologer.name.split(" ").map(x=>x[0]).join("")}</span><div><b>{astrologer.name}</b><span><Star/> {astrologer.rating} · ₹{astrologer.price_per_minute}/min · {astrologer.availability}</span></div><Button onClick={openProfile}>View astrologer</Button></div>:<Button variant="secondary" onClick={openProfile}>Browse {specialization} astrologers</Button>}</div>}

function Timeline({userId}:{userId:number}){
 const{data,error,reload}=useLoad(()=>api<LifeEvent[]>(`/api/users/${userId}/events`),[userId]);
 const[open,setOpen]=useState(false);const[editing,setEditing]=useState<LifeEvent|null>(null);const[form,setForm]=useState({title:"",date:futureISODate(3),category:"Career",description:"",importance:4});const[actionError,setActionError]=useState("");
 const fresh=()=>{setEditing(null);setForm({title:"",date:futureISODate(3),category:"Career",description:"",importance:4});setActionError("");setOpen(true)};
 const save=async()=>{setActionError("");try{if(editing)await put(`/api/events/${editing.id}`,form);else await post(`/api/users/${userId}/events`,form);setOpen(false);setEditing(null);reload()}catch(e){setActionError(e instanceof Error?e.message:"Could not save this event.")}};
 const remove=async(id:number)=>{if(confirm("Delete this life event?")){await del(`/api/events/${id}`);reload()}};
 if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;
 const rows=data.flatMap((event,index)=>{const eventDate=dateFromISO(event.date);const prior=index?dateFromISO(data[index-1].date):null;const newMonth=!prior||eventDate.getMonth()!==prior.getMonth()||eventDate.getFullYear()!==prior.getFullYear();return [
   ...(newMonth?[<div className="month" key={`month-${event.date}`}>{eventDate.toLocaleDateString("en",{month:"long"}).toUpperCase()} <span>{eventDate.getFullYear()}</span></div>]:[]),
   <div key={event.id} className="timelineEvent"><div className="timelineDate"><b>{eventDate.getDate()}</b><span>{eventDate.toLocaleDateString("en",{month:"short"}).toUpperCase()}</span></div><i/><div className="timelineBody"><span className="tag">{event.category}</span><h3>{event.title}</h3><p>{event.description||"No notes added."}</p><div className="eventGuidance"><Sparkles/><span><b>AstroTwin guidance</b> Protect a clear preparation window before this milestone.</span></div></div><div className="eventMeta"><b>{daysUntil(event.date)}</b><span>Importance {event.importance}/5</span><div><button onClick={()=>{setEditing(event);setForm({title:event.title,date:event.date,category:event.category,description:event.description,importance:event.importance});setActionError("");setOpen(true)}}>Edit</button><button onClick={()=>remove(event.id)} aria-label={`Delete ${event.title}`}><Trash2/></button></div></div></div>
  ]});
 return <><PageTitle eyebrow="YOUR STORY IN MOTION" title="Life Timeline" description="Give AstroTwin the moments that shape your decisions and reflections." action={<Button onClick={fresh}><Plus/> Add Life Event</Button>}/>{data.length===0?<EmptyState title="Your timeline is open" body="Add an upcoming milestone so AstroTwin can make future guidance more relevant." action={<Button onClick={fresh}>Add your first event</Button>}/>:<Card className="timeline">{rows}</Card>}{open&&<Modal title={editing?"Edit life event":"Add life event"} close={()=>setOpen(false)}><label>Title<input maxLength={180} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><div className="formGrid"><label>Date<input type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></label><label>Category<select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{["Career","Education","Relationship","Finance","Personal","Family"].map(x=><option key={x}>{x}</option>)}</select></label></div><label>Notes<textarea maxLength={2000} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label>Importance<select value={form.importance} onChange={e=>setForm({...form,importance:Number(e.target.value)})}>{[1,2,3,4,5].map(x=><option key={x}>{x}</option>)}</select></label>{actionError&&<p className="errorText">{actionError}</p>}<Button disabled={!form.title.trim()} onClick={save}>Save event</Button></Modal>}</>
}

function Memories({userId}:{userId:number}){
 const{data,error,reload}=useLoad(()=>api<Memory[]>(`/api/users/${userId}/memories`),[userId]);const[open,setOpen]=useState(false);const[editing,setEditing]=useState<Memory|null>(null);const[form,setForm]=useState({type:"Goal",content:"",importance:4});const[actionError,setActionError]=useState("");
 const fresh=()=>{setEditing(null);setForm({type:"Goal",content:"",importance:4});setActionError("");setOpen(true)};
 const save=async()=>{setActionError("");try{if(editing)await put(`/api/memories/${editing.id}`,form);else await post(`/api/users/${userId}/memories`,form);setOpen(false);reload()}catch(e){setActionError(e instanceof Error?e.message:"Could not save this memory.")}};
 const remove=async(id:number)=>{if(confirm("Forget this memory?")){await del(`/api/memories/${id}`);reload()}};
 if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;
 return <><PageTitle eyebrow="PERSISTENT CONTEXT" title="AstroTwin Memory" description={`${data.length} ${data.length===1?"memory helps":"memories help"} your guidance evolve with you.`} action={<Button onClick={fresh}><Plus/> Add memory</Button>}/>{data.length===0?<EmptyState title="Your memory is ready" body="Save a goal, meaningful event, or reflection to make future guidance more personal." action={<Button onClick={fresh}>Add your first memory</Button>}/>:<div className="memoryPageGrid">{data.map(m=><Card key={m.id} className={`memoryCard memory-${m.type.toLowerCase().replaceAll(" ","-")}`}><div className="cardHead"><span className={`memoryType ${m.type.toLowerCase().replace(" ","")}`}>{m.type}</span><span aria-label={`Importance ${m.importance} of 5`}>{"●".repeat(m.importance)}</span></div><p>{m.content}</p><footer><span>Remembered {formatDate(m.created_at.split("T")[0])}</span><div><button onClick={()=>{setEditing(m);setForm({type:m.type,content:m.content,importance:m.importance});setActionError("");setOpen(true)}}>Edit</button><button aria-label={`Delete ${m.type} memory`} onClick={()=>remove(m.id)}><Trash2/></button></div></footer></Card>)}</div>}{open&&<Modal title={editing?"Edit memory":"Add a memory"} close={()=>setOpen(false)}><label>Memory type<select value={form.type} onChange={e=>setForm({...form,type:e.target.value})}>{["Profile","Goal","Event","Reflection","Conversation Insight"].map(x=><option key={x}>{x}</option>)}</select></label><label>What should AstroTwin remember?<textarea maxLength={2000} rows={4} value={form.content} onChange={e=>setForm({...form,content:e.target.value})}/></label><label>Importance<select value={form.importance} onChange={e=>setForm({...form,importance:Number(e.target.value)})}>{[1,2,3,4,5].map(x=><option key={x}>{x}</option>)}</select></label>{actionError&&<p className="errorText">{actionError}</p>}<Button disabled={!form.content.trim()} onClick={save}>Save memory</Button></Modal>}</>
}

function Daily({userId}:{userId:number}){const{data,error,reload}=useLoad(()=>api<DashboardData>(`/api/users/${userId}/daily`),[userId]);if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;const g=data.guidance;const categories:[string,number,typeof Briefcase][]=[["Career",g.career_score,Briefcase],["Relationships",g.relationship_score,Heart],["Finance",g.finance_score,DollarSign],["Focus / Energy",g.energy_score,Zap]];return <><PageTitle eyebrow={fullDateLabel().toUpperCase()} title="Cosmic Daily" description="A daily reflection ritual personalized around the context of your life." action={<Button variant="secondary" onClick={()=>go("/resonance")}>View Resonance Report</Button>}/><div className="dailyGrid"><Card className="dailyHero"><ScoreRing value={g.overall_score}/><div><span className="sectionKicker">COSMIC MOMENTUM</span><h2>{g.insight}</h2><p>Let today be measured by clarity, not volume.</p></div></Card><Card className="categoryScores">{categories.map(([l,v,I])=><div key={l}><span className="iconBox"><I/></span><Progress label={l} value={v}/></div>)}</Card><Card className="recommended"><span className="iconBox"><Target/></span><div><span className="sectionKicker">RECOMMENDED ACTION</span><h3>{g.recommended_action}</h3></div></Card><Card className="trend"><div className="cardHead"><div><span className="sectionKicker">7-DAY RHYTHM</span><h2>Your momentum trend</h2></div><span className="delta"><TrendingUp/> Building</span></div><div className="chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data.history||[]}><defs><linearGradient id="cosmic" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#a98bff" stopOpacity={.55}/><stop offset="100%" stopColor="#a98bff" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#ffffff0a" vertical={false}/><XAxis dataKey="date" tickFormatter={x=>dateFromISO(x).toLocaleDateString("en",{weekday:"short"})} stroke="#817b99" axisLine={false}/><YAxis domain={[40,100]} hide/><Tooltip contentStyle={{background:"#17142a",border:"1px solid #ffffff14",borderRadius:12}}/><Area type="monotone" dataKey="overall_score" stroke="#b29aff" strokeWidth={3} fill="url(#cosmic)"/></AreaChart></ResponsiveContainer></div></Card><Reflection userId={userId} existing={data.reflection}/><Card className="upcomingCompact"><span className="sectionKicker">COMING INTO VIEW</span><h2>Upcoming life events</h2>{data.events.length?data.events.slice(0,3).map(e=><div key={e.id}><CalendarDays/><span><b>{e.title}</b><small>{formatDate(e.date)} · {daysUntil(e.date)}</small></span></div>):<div className="inlineEmpty"><CalendarDays/><span><b>No upcoming events</b><small>Add one from your Life Timeline.</small></span></div>}</Card></div></>}

function Resonance({userId}:{userId:number}){const{data,error,reload}=useLoad(()=>api<ResonanceData>(`/api/users/${userId}/resonance`),[userId]);if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;if(!data.total)return <EmptyState title="Your resonance report is ready to begin" body="Complete a daily reflection to see your personal guidance alignment over time." action={<Button onClick={()=>go("/daily")}>Complete today’s reflection</Button>}/>;return <><PageTitle eyebrow="REFLECTION HISTORY" title="Cosmic Resonance" description="How closely your guidance has aligned with your personal experience—not a measure of scientific predictive accuracy."/><div className="statGrid"><Card><span>Total check-ins</span><strong>{data.total}</strong><small>Your stored reflections</small></Card><Card><span>Strong resonance</span><strong>{data.strong}</strong><small>Felt closely aligned</small></Card><Card><span>Partial resonance</span><strong>{data.partial}</strong><small>Some alignment</small></Card><Card className="featured"><span>Overall resonance</span><strong>{data.score}%</strong><small>Personal guidance alignment</small></Card></div><div className="analyticsGrid"><Card className="trend"><h2>Weekly alignment trend</h2><div className="chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data.trend}><XAxis dataKey="date" hide/><YAxis domain={[0,100]} hide/><Tooltip/><Area type="monotone" dataKey="value" stroke="#c6a5ff" fill="#8d6bf144"/></AreaChart></ResponsiveContainer></div></Card><Card><h2>By life area</h2><p className="microcopy">{data.category_basis}</p>{Object.entries(data.categories).map(([k,v])=><Progress key={k} label={k} value={v}/>)}</Card></div><p className="responsibleNote"><ShieldCheck/> Resonance reflects your own check-ins and subjective guidance alignment. Astrology is not scientifically validated as a predictive system.</p></>}

function Circle({userId}:{userId:number}){const[step,setStep]=useState(1);const[loading,setLoading]=useState(false);const[error,setError]=useState("");const[type,setType]=useState("Co-founder");const[form,setForm]=useState({name:"Akshay",birth:"2001-11-08",time:"",city:""});const types=[["Friendship",Users],["Relationship",Heart],["Co-founder",Briefcase],["Roommate",Home],["Team",Zap]] as const;const generate=async()=>{setLoading(true);setError("");try{const r=await post<Report>("/api/compatibility",{user_id:userId,compatibility_type:type,person_b_name:form.name,person_b_birth_date:form.birth,person_b_birth_time:form.time,person_b_birth_city:form.city});go(`/circle/result/${r.id}`)}catch(e){setError(e instanceof Error?e.message:"Could not create report");setLoading(false)}};return <><PageTitle eyebrow="STRUCTURAL VIRALITY" title="AstroCircle" description="Explore how two people may communicate, decide and grow together."/>{loading?<Card className="circleGenerator"><div className="twoOrbs"><span>A</span><i/><span>{form.name[0]}</span></div><h2>Mapping your connection…</h2><p>Looking across communication, emotional rhythm, ambition and support.</p><div className="loadingLine"><i/></div></Card>:<Card className="circleForm"><div className="circleSteps"><span className={step>=1?"active":""}>1 <b>Connection</b></span><i/><span className={step>=2?"active":""}>2 <b>Their profile</b></span><i/><span>3 <b>Your match</b></span></div>{step===1?<><h2>What kind of connection is this?</h2><p>The lens changes how AstroTwin frames strengths and friction.</p><div className="typeGrid">{types.map(([x,I])=><button key={x} className={type===x?"selected":""} onClick={()=>setType(x)}><I/><b>{x}</b><Check/></button>)}</div><Button onClick={()=>setStep(2)}>Continue <ArrowRight/></Button></>:<><h2>Tell us about the other person.</h2><p>Birth time and city are optional for this prototype reflection.</p><label>Their name<input maxLength={120} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><div className="formGrid"><label>Date of birth<input type="date" value={form.birth} onChange={e=>setForm({...form,birth:e.target.value})}/></label><label>Birth time <small>Optional</small><input type="time" value={form.time} onChange={e=>setForm({...form,time:e.target.value})}/></label></div><label>Birth city <small>Optional</small><input maxLength={120} value={form.city} onChange={e=>setForm({...form,city:e.target.value})}/></label>{error&&<p className="errorText">{error}</p>}<div className="row"><Button variant="ghost" onClick={()=>setStep(1)}>Back</Button><Button disabled={!form.name.trim()||!form.birth} onClick={generate}>Generate Match <Sparkles/></Button></div></>}</Card>}</>}

function ReportView({id}:{id:string}){const{data,error,reload}=useLoad(()=>api<Report>(`/api/compatibility/${id}`),[id]);if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;return <ReportCard report={data}/>}
function SharedReport({shareId}:{shareId:string}){const{data,error,reload}=useLoad(()=>api<Report>(`/api/compatibility/share/${shareId}`),[shareId]);return <main className="sharedPage"><nav><Logo/><Button onClick={()=>go("/onboarding")}>Create Your Own AstroTwin</Button></nav>{error?<ErrorState message={error} retry={reload}/>:!data?<Loading/>:<><div className="shareBadge"><Share2/> A compatibility reflection shared with you</div><ReportCard report={data} publicView/><section className="shareCta"><Sparkles/><h2>Curious what your life context could reveal?</h2><p>Create an AstroTwin that remembers your goals, events and reflections.</p><Button onClick={()=>go("/onboarding")}>Create Your Own AstroTwin <ArrowRight/></Button></section></>}</main>}
function ReportCard({report,publicView=false}:{report:Report;publicView?:boolean}){const[shareStatus,setShareStatus]=useState("");const url=typeof window!=="undefined"?`${window.location.origin}/circle/share/${report.share_id}`:"";const markShared=()=>post(`/api/compatibility/${report.id}/shared`,{}).catch(()=>{});const copy=async()=>{try{await navigator.clipboard.writeText(url);await markShared();setShareStatus("Public link copied") }catch{setShareStatus("Copy unavailable—use the WhatsApp link instead.")}};const share=async()=>{try{if(navigator.share){await navigator.share({title:`${report.person_a_name} × ${report.person_b_name}`,text:`Our AstroCircle ${report.compatibility_type} match is ${report.overall_score}%`,url});await markShared();setShareStatus("Share sheet opened")}else await copy()}catch{setShareStatus("Sharing cancelled")}};const metrics:[[string,number],[string,number],[string,number],[string,number],[string,number]]=[["Communication",report.communication_score],["Emotional alignment",report.emotional_score],["Ambition",report.ambition_score],["Decision making",report.decision_score],["Trust / Support",report.trust_score]];return <div className="reportWrap"><Card className="reportHero"><div className="reportLabel"><span>{report.compatibility_type}</span><small>ASTROCIRCLE REFLECTION</small></div><div className="names"><span>{report.person_a_name[0]}</span><div><h1>{report.person_a_name} <em>×</em> {report.person_b_name}</h1><p>A connection shaped by momentum, candor and complementary rhythm.</p></div><span>{report.person_b_name[0]}</span></div><div className="matchScore"><ScoreRing value={report.overall_score}/><div><span>OVERALL MATCH</span><h2>A naturally energizing connection</h2><p>Your strongest pattern is the way shared ambition turns ideas into motion.</p></div></div></Card><div className="reportGrid"><Card><span className="sectionKicker">COMPATIBILITY PROFILE</span><h2>How this connection moves</h2>{metrics.map(([k,v])=><Progress key={k} label={k} value={v}/>)}</Card><Card className="insights"><div><span className="iconBox good"><TrendingUp/></span><h3>Natural strengths</h3>{report.strengths.map(x=><p key={x}><Check/> {x}</p>)}</div><div><span className="iconBox warn"><Zap/></span><h3>Potential friction</h3>{report.friction_points.map(x=><p key={x}><span>·</span> {x}</p>)}</div></Card></div><Card className="recommendation"><Sparkles/><div><span className="sectionKicker">REFLECTIVE RECOMMENDATION</span><h3>{report.recommendation}</h3></div></Card>{!publicView&&<><div className="shareActions"><Button onClick={share}><Share2/> Share Match</Button><Button variant="secondary" onClick={copy}><Copy/> Copy Link</Button><a className="button secondary" target="_blank" rel="noreferrer" onClick={markShared} href={`https://wa.me/?text=${encodeURIComponent(`Our AstroCircle match is ${report.overall_score}% ${url}`)}`}>WhatsApp</a><Button variant="ghost" onClick={()=>go("/circle")}>Create Another</Button></div><div className="shareStatus" aria-live="polite">{shareStatus}</div></>}<p className="responsibleNote"><ShieldCheck/> Designed for reflection and conversation—not a guarantee of relationship outcomes.</p></div>}

function Astrologers(){const[filters,setFilters]=useState({specialization:"",language:"",availability:""});const query=new URLSearchParams(Object.entries(filters).filter(([,v])=>v)).toString();const{data,error,reload}=useLoad(()=>api<Astrologer[]>(`/api/astrologers${query?`?${query}`:""}`),[query]);return <><PageTitle eyebrow="ASTROCONNECT" title="Meet your astrologer" description="When a question deserves depth, continue the reflection with a human guide."/><Card className="filters"><select aria-label="Filter by specialization" value={filters.specialization} onChange={e=>setFilters({...filters,specialization:e.target.value})}><option value="">All specializations</option>{["Career","Relationships","Finance","Vedic Astrology","Numerology","Tarot"].map(x=><option key={x}>{x}</option>)}</select><select aria-label="Filter by language" value={filters.language} onChange={e=>setFilters({...filters,language:e.target.value})}><option value="">All languages</option>{["English","Hindi","Bengali","Tamil"].map(x=><option key={x}>{x}</option>)}</select><select aria-label="Filter by availability" value={filters.availability} onChange={e=>setFilters({...filters,availability:e.target.value})}><option value="">Any availability</option><option value="online">Online now</option><option value="offline">Offline</option></select></Card>{error?<ErrorState message={error} retry={reload}/>:!data?<Loading/>:data.length?<div className="astrologerGrid">{data.map(a=><AstrologerCard key={a.id} a={a}/>)}</div>:<EmptyState title="No astrologers match these filters" body="Try another specialization, language, or availability." action={<Button onClick={()=>setFilters({specialization:"",language:"",availability:""})}>Clear filters</Button>}/>}</>}
function AstrologerCard({a}:{a:Astrologer}){return <Card className="astrologerCard"><div className="astroTop"><span className="avatar big">{a.name.split(" ").map(x=>x[0]).join("")}</span><span className={a.availability}>{a.availability}</span></div><span className="specialization">{a.specialization}</span><h2>{a.name}</h2><p>{a.bio}</p><div className="astroStats"><span><Star/> {a.rating} <small>({a.review_count})</small></span><span><Briefcase/> {a.experience_years} years</span></div><div className="price"><span>From</span><b>₹{a.price_per_minute}<small>/min</small></b></div><div className="row"><Button variant="secondary" onClick={()=>go(`/astrologers/${a.id}`)}>View Profile</Button><Button onClick={()=>go(`/consultation/${a.id}`)}>Talk Now</Button></div></Card>}
function AstrologerProfile({id,userId}:{id:string;userId:number}){const{data,error,reload}=useLoad(()=>api<Astrologer>(`/api/astrologers/${id}`),[id]);useEffect(()=>{const key=`astrotwin_profile_view_${id}`;if(!sessionStorage.getItem(key)){sessionStorage.setItem(key,"1");post("/api/analytics/event",{event_name:"astrologer_profile_viewed",user_id:userId,metadata:{astrologer_id:Number(id)}}).catch(()=>{})}},[id,userId]);if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;return <><a className="back" href="/astrologers">← Back to astrologers</a><Card className="profileHero"><span className="avatar huge">{data.name.split(" ").map(x=>x[0]).join("")}</span><div><span className="specialization">{data.specialization}</span><h1>{data.name} <span className="verified" aria-label="Verified demo astrologer"><Check/></span></h1><p>{data.bio}</p><div className="profileStats"><span><Star/> <b>{data.rating}</b> rating · {data.review_count} reviews</span><span><Briefcase/> <b>{data.experience_years} years</b> experience</span><span><MessageCircle/> {data.languages}</span></div></div><div className="bookingBox"><span>₹{data.price_per_minute}<small>/minute</small></span><b className={data.availability}>{data.availability==="online"?"Available now":"Next available today"}</b><Button onClick={()=>go(`/consultation/${data.id}?mode=call`)}>Talk Now</Button><Button variant="secondary" onClick={()=>go(`/consultation/${data.id}`)}>Book Session</Button></div></Card><div className="profileGrid"><Card><h2>Consultation approach</h2><p>Expect a grounded, conversational session. Your astrologer will use the context you choose to share and offer questions for reflection—not guarantees or instructions.</p><h3>Best for</h3><div className="contextChips"><span>Career transitions</span><span>Decision clarity</span><span>Confidence</span></div></Card><Card><h2>What you’ll get</h2>{["A focused reading around your question","Space to explore nuance with a human","Reflective notes you can carry forward"].map(x=><p key={x}><Check/> {x}</p>)}</Card></div></>}

function Consultation({id,userId}:{id:string;userId:number}){const{data,error,reload}=useLoad(()=>api<Astrologer>(`/api/astrologers/${id}`),[id]);const[form,setForm]=useState({date:futureISODate(1),time:"18:00",type:"call" as "call"|"chat"});const[confirmed,setConfirmed]=useState<ConsultationRecord|null>(null);const[bookingError,setBookingError]=useState("");const[saving,setSaving]=useState(false);useEffect(()=>{const bookingId=new URLSearchParams(window.location.search).get("booking");if(bookingId)api<ConsultationRecord>(`/api/consultations/${bookingId}`).then(setConfirmed).catch(e=>setBookingError(e.message))},[]);const book=async()=>{setSaving(true);setBookingError("");try{const record=await post<ConsultationRecord>("/api/consultations",{user_id:userId,astrologer_id:Number(id),consultation_type:form.type,scheduled_at:`${form.date}T${form.time}:00`});go(`/consultation/${id}?booking=${record.id}`)}catch(e){setBookingError(e instanceof Error?e.message:"Could not confirm this session.");setSaving(false)}};if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;if(confirmed){const scheduled=confirmed.scheduled_at;return <Card className="bookingSuccess"><div className="successOrb"><Check/></div><span className="eyebrow">SESSION CONFIRMED</span><h1>Your conversation is booked.</h1><p>{data.name} · {formatDate(scheduled.slice(0,10))} at {scheduled.slice(11,16)}</p><div className="confirmation"><CalendarDays/><span><b>{confirmed.consultation_type==="call"?"Voice call":"Chat session"}</b><small>Saved as consultation #{confirmed.id}. We’ll remind you before the session.</small></span></div><Button onClick={()=>go("/dashboard")}>Return to dashboard</Button></Card>}return <><PageTitle eyebrow="ASTROCONNECT BOOKING" title="Book a session" description="Choose a time and format. This demo confirms without payment."/><div className="bookingGrid"><Card><div className="bookingAstro"><span className="avatar big">{data.name.split(" ").map(x=>x[0]).join("")}</span><div><span className="specialization">{data.specialization}</span><h2>{data.name}</h2><p><Star/> {data.rating} · {data.experience_years} years</p></div></div><hr/><h3>Session format</h3><div className="typeGrid two">{([["call","Voice call",Clock3],["chat","Chat",MessageCircle]] as const).map(([v,l,I])=><button key={v} className={form.type===v?"selected":""} onClick={()=>setForm({...form,type:v})}><I/><b>{l}</b><Check/></button>)}</div><div className="formGrid"><label>Date<input min={localISODate()} type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></label><label>Time<select value={form.time} onChange={e=>setForm({...form,time:e.target.value})}>{["10:00","12:30","16:00","18:00","20:30"].map(x=><option key={x}>{x}</option>)}</select></label></div></Card><Card className="bookingSummary"><span className="sectionKicker">BOOKING SUMMARY</span><div><span>Astrologer</span><b>{data.name}</b></div><div><span>Duration</span><b>20 minutes</b></div><div><span>Rate</span><b>₹{data.price_per_minute}/min</b></div><div className="total"><span>Demo total</span><b>₹{data.price_per_minute*20}</b></div><p><ShieldCheck/> No payment will be collected in this prototype.</p>{bookingError&&<p className="errorText">{bookingError}</p>}<Button disabled={saving} onClick={book}>{saving?"Confirming…":<>Confirm booking <Check/></>}</Button></Card></div></>}

function SettingsView({userId}:{userId:number}){const{data,error,reload,setData}=useLoad(()=>api<User>(`/api/users/${userId}`),[userId]);const[done,setDone]=useState(false);if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;const save=async()=>{const u=await put<User>(`/api/users/${userId}`,data);setData(u);setDone(true);setTimeout(()=>setDone(false),2000)};return <><PageTitle eyebrow="YOUR PROFILE" title="Settings" description="Control what your AstroTwin knows and how it stays in touch."/><div className="settingsGrid"><Card><h2>Birth profile</h2><label>Name<input value={data.name} onChange={e=>setData({...data,name:e.target.value})}/></label><div className="formGrid"><label>Date of birth<input type="date" value={data.birth_date} onChange={e=>setData({...data,birth_date:e.target.value})}/></label><label>Birth time<input type="time" value={data.birth_time} onChange={e=>setData({...data,birth_time:e.target.value})}/></label></div><label>Birth city<input value={data.birth_city} onChange={e=>setData({...data,birth_city:e.target.value})}/></label><label>Primary focus<select value={data.primary_focus} onChange={e=>setData({...data,primary_focus:e.target.value})}>{["Career","Relationships","Finance","Personal Growth","Education","Family"].map(x=><option key={x}>{x}</option>)}</select></label><Button onClick={save}>{done?<><Check/> Saved</>:"Save changes"}</Button></Card><Card><h2>Notifications</h2><p>Choose the rhythm that supports reflection without becoming noise.</p>{[["daily","Daily cosmic briefing"],["events","Life-event reminders"],["none","No notifications"]].map(([v,l])=><label className="radio" key={v}><input type="radio" checked={data.notifications===v} onChange={()=>setData({...data,notifications:v})}/><span><b>{l}</b><small>{v==="daily"?"A quiet prompt each morning":v==="events"?"Only before important milestones":"You can still visit anytime"}</small></span></label>)}</Card><Card className="responsible"><ShieldCheck/><div><h2>Responsible guidance</h2><p>AstroTwin provides astrology-based reflective guidance for entertainment and personal exploration. It should not replace professional medical, legal, financial or mental-health advice.</p></div></Card></div></>}

function Analytics(){const{data,error,reload}=useLoad(()=>api<AnalyticsData>("/api/admin/analytics"),[]);if(error)return <ErrorState message={error} retry={reload}/>;if(!data)return <Loading/>;const cards:[string,number,string][]=[["Stored profiles",data.total_users,"Seeded demo + profiles created here"],["Daily check-ins",data.daily_reflections,"Seeded demo + live records"],["AstroTwin questions",data.questions,"Seeded demo + live events"],["Compatibility reports",data.compatibility_reports,"Seeded demo + live events"],["Share actions",data.shares,"Seeded demo + live events"],["Astrologer recommendations",data.recommendations,"Seeded demo + live events"],["Consultations booked",data.bookings,"Seeded demo + live records"]];return <><PageTitle eyebrow="HACKATHON CONTROL ROOM" title="Illustrative Product Analytics" description="A transparent prototype baseline that updates with interactions created during this demo." action={<span className="dataMode"><span/> {data.data_mode}</span>}/><Card className="analyticsNotice"><ShieldCheck/><div><b>Demo assumptions—not measured AstroLive results</b><p>Retention, engagement and viral-loop values below are illustrative targets for experiment design. Event totals combine fictional seeded activity with interactions created in this prototype.</p></div></Card><div className="statGrid analytics">{cards.map(([label,value,note])=><Card key={label}><span>{label}</span><strong>{value}</strong><small>{note}</small></Card>)}<Card className="featured"><span>Demo recommendation → booking</span><strong>{data.conversion_rate}%</strong><small>{data.recommendations?"Prototype bookings ÷ recommendations":"No recommendations yet"}</small></Card></div><div className="metricGroups"><Card><span className="sectionKicker">ILLUSTRATIVE RETENTION</span><h2>Habit formation</h2><div className="bigMetrics"><div><b>{data.metrics.d1_retention}%</b><span>D1 hypothesis</span></div><div><b>{data.metrics.d7_retention}%</b><span>D7 hypothesis</span></div><div><b>{data.metrics.daily_opens}</b><span>Seeded daily opens</span></div></div></Card><Card><span className="sectionKicker">ILLUSTRATIVE VIRAL LOOP</span><h2>AstroCircle acquisition</h2><div className="formula"><span>K = invites × conversion</span><strong>{data.metrics.viral_coefficient}</strong></div><p>{data.metrics.invites_per_user} invites/user × {Math.round(data.metrics.invite_conversion*100)}% conversion · demo assumptions</p></Card><Card><span className="sectionKicker">ILLUSTRATIVE ENGAGEMENT</span><h2>Context depth</h2><Progress label="Questions / user" value={data.metrics.questions_per_user*20}/><Progress label="Memories / user" value={data.metrics.memories_per_user*12}/></Card></div><Card className="funnel"><h2>Prototype monetization funnel</h2>{[["AstroTwin questions",data.questions],["Astrologer recommendations",data.recommendations],["Profile views",data.events.astrologer_profile_viewed||0],["Bookings",data.bookings]].map(([label,value],index)=><div key={label as string} style={{width:`${100-index*18}%`}}><span>{label as string}</span><b>{value as number}</b></div>)}</Card></>}

function Modal({title,close,children}:{title:string;close:()=>void;children:React.ReactNode}){return <div className="modalBackdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><motion.div role="dialog" aria-modal="true" aria-label={title} initial={{opacity:0,y:20}} animate={{opacity:1,y:0}} className="modal"><div className="cardHead"><h2>{title}</h2><button aria-label="Close dialog" onClick={close}><X/></button></div>{children}</motion.div></div>}
function AccessGate({onDemo}:{onDemo:()=>void}){return <main className="accessGate"><Logo/><Card><Sparkles/><h1>Your AstroTwin is waiting.</h1><p>Sign in to your private chart and memories, create a new Vedic astrology profile, or explore the fictional judge demo.</p><Button onClick={()=>go("/login")}><LogIn/> Sign in</Button><Button variant="secondary" onClick={()=>go("/onboarding")}>Create account and chart</Button><Button variant="ghost" onClick={onDemo}>Explore Seeded Demo</Button></Card></main>}
